const item = $input.item;
const incomingJson = { ...(item.json ?? {}) };
const media = item.binary?.media;

if (!media) {
  return [{
    json: {
      ok: false,
      status: 400,
      action: 'media_moderate',
      allowed: false,
      safe_to_post: false,
      needs_review: false,
      reason_codes: ['missing-media-binary'],
      summary: 'ไม่พบไฟล์ media ใน multipart/form-data'
    }
  }];
}

return [{
  json: incomingJson,
  binary: {
    media
  }
}];

const item = $input.item;
const incomingJson = { ...(item.json ?? {}) };
const media = item.binary?.media;
const mimeType = String(media?.mimeType ?? media?.fileType ?? '').toLowerCase();
const fileName = String(media?.fileName ?? '').toLowerCase();

let mediaType = 'unknown';
if (mimeType.startsWith('image/') || /\.(png|jpe?g|webp|gif|heic|heif)$/i.test(fileName)) {
  mediaType = 'image';
} else if (mimeType.startsWith('video/') || /\.(mp4|mov|m4v|avi|webm|mkv)$/i.test(fileName)) {
  mediaType = 'video';
}

const moderationPrompt = `You are a safety moderator for user-generated media.
Analyze the attached media binary directly (image or video).
If media_type is video, also use transcript text when provided.

Return ONLY valid JSON with this schema:
{
  "allowed": boolean,
  "safe_to_post": boolean,
  "needs_review": boolean,
  "reason_codes": string[],
  "summary": string
}

Rules:
- Block explicit sexual content, nudity, minors in sexual context, graphic violence, self-harm promotion, hate symbols, illegal activity promotion.
- If uncertain, set needs_review=true and allowed=false.
- If safe, use reason_codes=["safe"] and summary in Thai.`;

return [{
  json: {
    ...incomingJson,
    media_type: mediaType,
    mime_type: mimeType,
    file_name: media?.fileName ?? '',
    moderation_prompt: moderationPrompt
  },
  binary: {
    media
  }
}];

if (($json.media_type ?? '').toString().toLowerCase() !== 'image') {
  return [];
}

const toBool = (value, fallback = false) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value !== 0;
  if (typeof value === 'string') {
    const v = value.trim().toLowerCase();
    if (['true', '1', 'yes'].includes(v)) return true;
    if (['false', '0', 'no'].includes(v)) return false;
  }
  return fallback;
};

const toStringArray = (value, fallback = ['safe']) => {
  if (!Array.isArray(value)) return fallback;
  const arr = value.map((v) => String(v ?? '').trim()).filter((v) => v.length > 0);
  return arr.length > 0 ? arr : fallback;
};

const pickRaw = () => {
  const candidates = [
    $json?.choices?.[0]?.message?.content,
    $json?.message?.content,
    $json?.content,
    $json?.text,
    $json?.output,
    $json?.response,
    $json
  ];
  for (const value of candidates) {
    if (value !== undefined && value !== null && value !== '') {
      return value;
    }
  }
  return null;
};

const parseObject = (raw) => {
  if (!raw) return {};
  if (typeof raw === 'object') return raw;
  const text = String(raw).trim();
  if (!text) return {};
  try {
    return JSON.parse(text);
  } catch {
    const start = text.indexOf('{');
    const end = text.lastIndexOf('}');
    if (start >= 0 && end > start) {
      try {
        return JSON.parse(text.slice(start, end + 1));
      } catch {}
    }
  }
  return {};
};

const parsed = parseObject(pickRaw());
const allowed = toBool(parsed.allowed, false);
const safeToPost = toBool(parsed.safe_to_post ?? parsed.safeToPost, allowed);
const needsReview = toBool(parsed.needs_review ?? parsed.needsReview, !allowed);
const reasonCodes = toStringArray(parsed.reason_codes ?? parsed.reasonCodes, allowed ? ['safe'] : ['blocked']);
const summary = String(parsed.summary ?? (allowed ? 'สามารถโพสต์ได้' : 'ไม่อนุญาตให้โพสต์')).trim() || (allowed ? 'สามารถโพสต์ได้' : 'ไม่อนุญาตให้โพสต์');

return [{
  json: {
    ok: true,
    status: 200,
    action: 'image_moderate',
    allowed,
    safe_to_post: safeToPost,
    needs_review: needsReview,
    reason_codes: reasonCodes,
    summary
  }
}];

